 public Yaf_Route_Regex::__construct
 stringmatch
 arrayroute
 arraynullmap&null;
 arraynullverify&null;
 stringnullreverse&null;


 Construit une route Yaf_Route_Regex, qui route une
 URI de requête correspondant à une expression rationnelle vers un module,
 un contrôleur et une action.

  &reftitle.examples;

   Yaf_Route_Regex via Yaf_Router::addRoute


<?php

/**
 * Ajoute une route regex à la pile de routes de Yaf_Router
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute(
    "name",
    new Yaf_Route_Regex(
        "#^/product/([^/]+)/([^/]+)#", // correspond aux URI commençant par "/product"
        array(
            'controller' => "product", // route vers le contrôleur product
        ),
        array(
            1 => "name", // $request->getParam("name") contient la première capture
            2 => "id",   // et $request->getParam("id") la seconde
        )
    )
);
?>




   Yaf_Route_Regex utilisant une capture comme nom de contrôleur


<?php

/**
 * Utilise une capture comme nom de contrôleur
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute(
    "name",
    new Yaf_Route_Regex(
        "#^/product/([^/]+)/([^/]+)#i", // correspond aux URI commençant par "/product"
        array(
            'controller' => ":name", // la capture "name" (voir map) devient le contrôleur
        ),
        array(
            1 => "name", // $request->getParam("name") contient la première capture
            2 => "id",   // et $request->getParam("id") la seconde
        )
    )
);
?>




   Yaf_Route_Regex utilisant un groupe de capture nommé


<?php

/**
 * Utilise un groupe de capture nommé comme nom de contrôleur
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute(
    "name",
    new Yaf_Route_Regex(
        "#^/product/(?<name>[^/]+)/([^/]+)#i", // correspond aux URI commençant par "/product"
        array(
            'controller' => ":name", // la capture "name" devient le contrôleur
        ),
        array(
            2 => "id", // le groupe 1 est nommé, seul le groupe 2 nécessite une entrée dans map
        )
    )
);
?>




   Yaf_Route_Regex via Yaf_Router::addConfig


<?php

/**
 * Ajoute une route regex à la pile de routes de Yaf_Router via un tableau de configuration
 */
$config = array(
    "name" => array(
        "type"  => "regex",          // une route Yaf_Route_Regex
        "match" => "#(.*)#",         // correspond à n'importe quelle URI de requête
        "route" => array(
            'controller' => "product", // route vers le contrôleur product
            'action'     => "dummy",   // et vers l'action dummy
        ),
        "map" => array(
            1 => "uri", // $request->getParam("uri") contient l'URI correspondante
        ),
    ),
);

Yaf_Dispatcher::getInstance()->getRouter()->addConfig(
    new Yaf_Config_Simple($config)
);
?>
